//! Saves exports generated by the UI as new files in the user's Downloads folder.
//!
//! The UI supplies only the content and the period; the file name is built
//! here from validated dates, and existing files are never overwritten.

use std::fs::OpenOptions;
use std::io::Write;
use std::path::{Path, PathBuf};

const MAX_BYTES: usize = 50 * 1024 * 1024;

fn is_date(s: &str) -> bool {
    let b = s.as_bytes();
    b.len() == 10
        && b[4] == b'-'
        && b[7] == b'-'
        && b.iter().enumerate().all(|(i, c)| i == 4 || i == 7 || c.is_ascii_digit())
}

pub fn save_csv(dir: &Path, start: &str, end: &str, stamp: &str, content: &str) -> Result<PathBuf, String> {
    if !is_date(start) || !is_date(end) {
        return Err("Export period must use YYYY-MM-DD".into());
    }
    if content.len() > MAX_BYTES {
        return Err("Export is too large".into());
    }
    std::fs::create_dir_all(dir).map_err(|e| format!("Cannot create export folder: {e}"))?;
    for n in 0..100 {
        let suffix = if n == 0 { String::new() } else { format!("-{n}") };
        let path = dir.join(format!("MoneyManager-{start}_{end}-{stamp}{suffix}.csv"));
        match OpenOptions::new().write(true).create_new(true).open(&path) {
            Ok(mut file) => {
                file.write_all(content.as_bytes()).map_err(|e| format!("Cannot write export: {e}"))?;
                return Ok(path);
            }
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(e) => return Err(format!("Cannot write export: {e}")),
        }
    }
    Err("Too many exports with the same name".into())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn writes_new_files_and_validates_period() {
        let dir = std::env::temp_dir().join(format!("mm-export-test-{}", std::process::id()));
        let a = save_csv(&dir, "2026-08-01", "2026-08-31", "120000", "a,b\r\n").unwrap();
        let b = save_csv(&dir, "2026-08-01", "2026-08-31", "120000", "c\r\n").unwrap();
        assert_ne!(a, b);
        assert_eq!(std::fs::read_to_string(&a).unwrap(), "a,b\r\n");
        assert!(a.file_name().unwrap().to_str().unwrap().starts_with("MoneyManager-2026-08-01_2026-08-31"));
        assert!(save_csv(&dir, "../../etc", "2026-08-31", "1", "x").is_err());
        std::fs::remove_dir_all(&dir).unwrap();
    }
}
